<?php
/**
 * deploy.php - Local Deployment Sender
 * ─────────────────────────────────────────────────────────────────────────────
 * Target   : https://hackathon.codly.in/update.php
 * Subdomain: hackathon.codly.in
 *
 * Run from the project root directory after making changes:
 *
 *   Usage:    php deploy.php <file1> [file2] [file3] ...
 *   Example:  php deploy.php index.php
 *   Example:  php deploy.php includes/header.php css/style.css
 *
 * ─────────────────────────────────────────────────────────────────────────────
 * NOTE: Do NOT upload this file to the live server.
 * Generated by Codly India Deploy System. Keep SECRET_KEY private.
 * ─────────────────────────────────────────────────────────────────────────────
 */

define('SECRET_KEY', '283c30c451da4480c1ac090ef41da860e364b20929f1d1f58171d785c792ab94');
define('SERVER_URL', 'https://hackathon.codly.in/update.php');
define('LOCAL_ROOT', __DIR__);

function green(string $t): string  { return "\033[32m{$t}\033[0m"; }
function red(string $t): string    { return "\033[31m{$t}\033[0m"; }
function yellow(string $t): string { return "\033[33m{$t}\033[0m"; }
function bold(string $t): string   { return "\033[1m{$t}\033[0m"; }
function cyan(string $t): string   { return "\033[36m{$t}\033[0m"; }
function println(string $line = ''): void { echo $line . PHP_EOL; }

if (PHP_SAPI !== 'cli') { die("Run from command line only.\n"); }

if ($argc < 2) {
    println(bold("Usage:") . "  php deploy.php <file1> [file2] ...");
    println("Target: " . SERVER_URL);
    exit(1);
}

$files_to_send = array_slice($argv, 1);

println();
println(bold(cyan("═══ Codly Deploy — hackathon.codly.in ═══")));
println(cyan("  Target : " . SERVER_URL));
println(cyan("  Files  : " . count($files_to_send)));
println();

$payload_files = [];
$skipped       = 0;

foreach ($files_to_send as $rel_path) {
    $rel_path = str_replace('\\', '/', trim($rel_path));
    $rel_path = ltrim($rel_path, '/');

    // Never allow traversal or credential/config files to leave the workspace.
    if ($rel_path === '' || preg_match('~(^|/)\.\.(/|$)~', $rel_path)
        || preg_match('~(^|/)(\.env(?:\.[^/]*)?|\.git|\.venv|node_modules)(/|$)~i', $rel_path)
        || preg_match('~(^|/)(config\.php|[^/]+\.(pem|key|p12|pfx))$~i', $rel_path)) {
        println("  " . red("✗ BLOCKED") . "  {$rel_path}  (unsafe or sensitive path)");
        $skipped++;
        continue;
    }

    $root_real = realpath(LOCAL_ROOT);
    $local_abs = realpath(LOCAL_ROOT . DIRECTORY_SEPARATOR . str_replace('/', DIRECTORY_SEPARATOR, $rel_path));
    $root_prefix = $root_real === false ? '' : rtrim($root_real, DIRECTORY_SEPARATOR) . DIRECTORY_SEPARATOR;

    if ($root_real === false || $local_abs === false) {
        println("  " . red("✗ NOT FOUND") . "  {$rel_path}");
        $skipped++;
        continue;
    }
    if (stripos($local_abs, $root_prefix) !== 0) {
        println("  " . red("✗ BLOCKED") . "  {$rel_path}  (outside project root)");
        $skipped++;
        continue;
    }
    if (!is_file($local_abs)) {
        println("  " . yellow("⚠ SKIPPED") . "   {$rel_path}  (not a file)");
        $skipped++;
        continue;
    }

    $content = file_get_contents($local_abs);
    $size_kb = round(strlen($content) / 1024, 1);
    $payload_files[] = ['path' => $rel_path, 'content' => base64_encode($content), 'encoding' => 'base64'];
    println("  " . green("✓ QUEUED") . "    {$rel_path}  ({$size_kb} KB)");
}

println();

if (count($payload_files) === 0) {
    println(red("No valid files to deploy. Aborting."));
    exit(1);
}

$payload = json_encode(['files' => $payload_files]);
println("Sending to live server...");
println();

$ch = curl_init(SERVER_URL);
curl_setopt_array($ch, [
    CURLOPT_POST           => true,
    CURLOPT_POSTFIELDS     => $payload,
    CURLOPT_RETURNTRANSFER => true,
    CURLOPT_TIMEOUT        => 60,
    CURLOPT_HTTPHEADER     => [
        'Content-Type: application/json',
        'Authorization: Bearer ' . SECRET_KEY,
        'Content-Length: ' . strlen($payload),
    ],
    CURLOPT_SSL_VERIFYPEER => true,
    CURLOPT_SSL_VERIFYHOST => 2,
]);

$response   = curl_exec($ch);
$http_code  = curl_getinfo($ch, CURLINFO_HTTP_CODE);
$curl_error = curl_error($ch);
unset($ch);

if ($curl_error) { println(red("Connection error: " . $curl_error)); exit(1); }

$result = json_decode($response, true);
if (!is_array($result)) {
    println(red("Unexpected server response (HTTP {$http_code}); response body suppressed.")); exit(1);
}

if (!empty($result['deployed'])) {
    println(bold(green("✓ Successfully Deployed:")));
    foreach ($result['deployed'] as $f) {
        $kb = round($f['bytes'] / 1024, 1);
        println("    " . green("→") . "  {$f['path']}  ({$kb} KB)");
    }
    println();
}

if (!empty($result['errors'])) {
    println(bold(red("✗ Errors:")));
    foreach ($result['errors'] as $e) {
        println("    " . red("→") . "  {$e['path']}:  {$e['error']}");
    }
    println();
}

$summary = $result['summary'] ?? "HTTP {$http_code}";
if ($result['success'] ?? false) {
    println(green(bold("✓ Deployment complete:")) . "  {$summary}");
} else {
    println(yellow(bold("⚠ Finished with issues:")) . "  {$summary}");
}

println();
exit(($result['success'] ?? false) ? 0 : 1);
